# A sample status-line command for output compatibility checks.
input=$(cat); current_dir=$(echo "$input" | jq -r '.workspace.current_dir'); git_branch=""; if git -C "$current_dir" rev-parse --git-dir > /dev/null 2>&1; then branch=$(git -C "$current_dir" -c core.filesRefLockTimeout=0 symbolic-ref --short HEAD 2>/dev/null || echo "detached"); if [ -n "$branch" ]; then git_branch="[$branch] "; fi; fi; model=$(echo "$input" | jq -r '.model.display_name'); usage=$(echo "$input" | jq '.context_window.current_usage'); if [ "$usage" != "null" ]; then input_tokens=$(echo "$usage" | jq '.input_tokens'); output_tokens=$(echo "$usage" | jq '.output_tokens'); cache_creation=$(echo "$usage" | jq '.cache_creation_input_tokens'); cache_read=$(echo "$usage" | jq '.cache_read_input_tokens'); window_size=$(echo "$input" | jq '.context_window.context_window_size'); current_context=$((input_tokens + cache_creation + cache_read)); total_tokens=$((current_context + output_tokens)); if [ "$window_size" -gt 0 ]; then pct=$((current_context * 100 / window_size)); context_info="${pct}% ctx | ${total_tokens} tokens"; else context_info="${total_tokens} tokens"; fi; else context_info="0% ctx"; fi; printf "%s%s | %s | %s" "$git_branch" "$current_dir" "$model" "$context_info"
